public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Creates a topic in a forum supergroup chat or a chat with a bot with topics; requires can_manage_topics administrator or can_create_topics member right in the supergroup
    /// </summary>
    public Task<TdLib.TdApi.Objects.ForumTopicInfo> CreateForumTopicAsync(long chatId = default, string name = default, bool isNameImplicit = default, ForumTopicIcon icon = default)
    {

           using var activity =  StartCallActivity("CreateForumTopicAsync", typeof(CreateForumTopic).FullName ?? "CreateForumTopicAsync");

           try
           {
             return client.CreateForumTopicAsync(chatId, name, isNameImplicit, icon);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
